    local st = M.st(5)
    if not st.hasPhone or (tonumber(st.phoneCharges) or 0) > 0 or st.phonePaused then return false end
    local P = M.r("Phone")
    if not P then return false end
    S.phone = "playing"
    F.phoneWait = false
    local hold = M.r("PhoneHold")
    if hold then pcall(function() hold:FireServer(true) end) end
    task.wait(0.5)
    pcall(function() P:FireServer("start") end)
    local t0, at = os.clock(), 0
    local n = tonumber(val("f_pipes", 101)) or 101
    for i = 1, n do
        if not RUNNING or not on("f_phone") or F.phoneWait then break end
        at += (i == 1) and 1.7 or 1.5 / (1 + 0.002 * (i - 1))
        local w = t0 + at + 0.03 - os.clock()
        if w > 0 then task.wait(w) end
        pcall(function() P:FireServer("pipe", i) end)
        S.pipes = i
    end
    if not F.phoneWait then pcall(function() P:FireServer("crash") end) F.phoneGames += 1 LOG("phone game", n) end
    if hold then pcall(function() hold:FireServer(false) end) end
    S.phone = "done"
    M.stateAt = 0
    task.wait(2)
    return true
end
