RW.codes = { "UPDATE3", "UPDATE2", "UPDATE1" }
RW.at = {}
RW.codesDone = false
function RW.every(k, s)
    if (RW.at[k] or 0) > os.clock() then return false end
    RW.at[k] = os.clock() + s
    return true
end
function RW.items(st)
    local inv = st.inv or {}
    local pot = inv.pot or {}
    local now = tonumber(st.now) or os.time()
    for _, sl in ipairs(inv.slots or {}) do
        local id = tostring(sl.id)
        if (tonumber(sl.n) or 0) > 0 then
            local pre, kind = id:match("^(%a+)_(%a+)")
            if (pre == "potion" or pre == "elixir") and on("r_potions") then
                local p = kind and pot[kind]
                local ends = type(p) == "table" and tonumber(p.ends) or nil
                if not ends or ends <= now then M.call("Inventory", "use", id) S.items += 1 LOG("use", id) return true end
            elseif pre == "roll" and on("r_lucky") and not inv.lucky and not inv.next then
                M.call("Inventory", "use", id) S.items += 1 LOG("use", id) return true
            elseif pre == "coupon" and on("r_lucky") and not inv.next and not inv.lucky then
                M.call("Inventory", "use", id) S.items += 1 LOG("use", id) return true
            end
        end
    end
    return false
end
RW.stallPrice = { 10000, 100000, 500000, 10000000 }
function RW.stall(st)
    if not on("r_stall") or not st.hasStall or not RW.every("stall", 20) then return end
    local data = M.call("Stall", "get")
    local left = type(data) == "table" and type(data.data) == "table" and data.data.left or {}
    local pot = (st.inv or {}).pot or {}
    local now = tonumber(st.now) or os.time()
    local have = {}
    for _, sl in ipairs((st.inv or {}).slots or {}) do local k = tostring(sl.id):match("^potion_(%a+)") if k and (tonumber(sl.n) or 0) > 0 then have[k] = true end end
    local money = tonumber(st.money) or 0
    local kinds = Opt and Opt.r_stallKinds and Opt.r_stallKinds.Value
    for _, kind in ipairs({ "money", "luck", "speed" }) do
        local wanted = type(kinds) ~= "table" or kinds[kind:sub(1, 1):upper() .. kind:sub(2)]
        local p = pot[kind]
        local active = type(p) == "table" and (tonumber(p.ends) or 0) > now
        if wanted and not active and not have[kind] then
            for lv = math.clamp(tonumber(val("r_stallMax", 2)) or 2, 1, 4), 1, -1 do
                local key = "potion_" .. kind .. "_" .. lv
                local price = RW.stallPrice[lv]
                if (tonumber(left[key]) or 0) > 0 and money >= price * 20 then
                    local r = M.call("Stall", "buy", key)
                    if type(r) == "table" and r.ok then S.items += 1 LOG("stall buy", key) money -= price end
                    break
                end
            end
        end
    end
end
function RW.tick()
    local st = M.st(3)
    RW.stall(st)
    if on("r_codes") and not RW.codesDone then
        RW.codesDone = true
        for _, c in ipairs(RW.codes) do M.call("RedeemCode", c) task.wait(3) end
    end
    if on("r_wheel") and RW.every("wheel", 15) then
        local dl = st.daily or {}
        local spun = false
        for _, day in pairs(dl.pending or {}) do
            local r = M.call("WheelSpin", tonumber(day) or day)
            if type(r) == "table" and r.ok then S.spins += 1 spun = true LOG("wheel", day, r.prize) end
            task.wait(1.5)
        end
        for _ = 1, math.min(tonumber(dl.extra) or 0, 10) do
            local r = M.call("WheelSpin", 0)
            if type(r) == "table" and r.ok then S.spins += 1 spun = true LOG("wheel extra", r.prize) else break end
            task.wait(1.5)
        end
        if spun then M.refresh() end
    end
    if on("r_tasks") and RW.every("tasks", 15) then
        local tk = st.tasks or {}
        local prog, claimed = tk.progress or {}, tk.claimed or {}
        for _, t in pairs(tk.list or {}) do
            local id = type(t) == "table" and t.id
            local need = type(t) == "table" and tonumber(t.need) or math.huge
            if id and not claimed[id] and (tonumber(prog[id]) or 0) >= need then
                local r = M.call("ClaimTask", id)
                if type(r) == "table" and r.ok then S.claims += 1 LOG("task", id) end
            end
        end
        local wk = st.weekly or tk.weekly
        if type(wk) == "table" and not wk.claimed and (tonumber(wk.progress) or 0) >= (tonumber(wk.need) or math.huge) then
            local r = M.call("ClaimTask", "weekly")
            if type(r) == "table" and r.ok then S.claims += 1 LOG("weekly") end
        end
    end
    if on("r_upkeep") and RW.every("upkeep", 60) then
        local s = M.refresh() or st
        local now = tonumber(s.now) or os.time()
        for _, it in ipairs(s.inventory or {}) do
            local pu = tonumber(it.paidUntil or (it.plate and it.plate.paidUntil)) or 0
            if pu - now < 86400 and not it.listingId then
                local r = M.call("PayUpkeep", it.uid, 1)
                if r then S.upkeep += tonumber(it.dailyCost) or 0 end
            end
        end
    end
    if on("r_equip") and RW.every("equip", 30) then M.call("EquipBest") end
    RW.items(st)
end
